CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_pathway]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_pathway]
	(
		[apuk_code],
		[apuk_currentversion],
		[apuk_name],
		[apuk_pathwaygroup],
		[apuk_pathwayid],
		[apuk_pathwaytype],
		[apuk_professionalgroupid],
		[apuk_professionalgroupid_entitytype],
		[apuk_professionalgroupidname],
		[apuk_recognisedqualificationid],
		[apuk_recognisedqualificationid_entitytype],
		[apuk_recognisedqualificationidname],
		[apuk_showareasofpractice],
		[apuk_showindustrysector],
		[apuk_showspecialisms],
		[apuk_versionnumber],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_code],
		stg.[apuk_currentversion],
		stg.[apuk_name],
		stg.[apuk_pathwaygroup],
		stg.[apuk_pathwayid],
		stg.[apuk_pathwaytype],
		stg.[apuk_professionalgroupid],
		stg.[apuk_professionalgroupid_entitytype],
		stg.[apuk_professionalgroupidname],
		stg.[apuk_recognisedqualificationid],
		stg.[apuk_recognisedqualificationid_entitytype],
		stg.[apuk_recognisedqualificationidname],
		stg.[apuk_showareasofpractice],
		stg.[apuk_showindustrysector],
		stg.[apuk_showspecialisms],
		stg.[apuk_versionnumber],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_pathway] stg
		LEFT JOIN [synapse_ce].[apuk_pathway] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
